const app = document.querySelector("[data-app]");
const crumb = document.querySelector("[data-project-crumb]");
const newButton = document.querySelector("[data-new-project]");
const exportButton = document.querySelector("[data-export-project]");
const toast = document.querySelector("[data-toast]");
const helpDialog = document.querySelector("[data-help-dialog]");
let language = localStorage.getItem("zavod-ui-language") || "hy";
let sourceType = "screenplay";
let sourceFile = null;
let sourcePdfPages = null;
let project = null;
let activeView = "overview";
let activeSceneId = null;
let activeSlide = 0;
let activeDay = 1;
let sceneFilter = "all";

const t = key => translations[language][key] || translations.en[key] || key;
const esc = value => String(value ?? "").replace(/[&<>'"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[char]);
const slug = value => String(value || "project").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-|-$/g, "").slice(0, 60) || "project";
const unique = values => [...new Set(values.filter(Boolean))];

function setLanguage(next) {
  language = next;
  localStorage.setItem("zavod-ui-language", language);
  document.documentElement.lang = language;
  document.querySelectorAll("[data-lang]").forEach(button => button.classList.toggle("is-active", button.dataset.lang === language));
  if (project) renderWorkspace(); else renderStart();
  updateHeader();
}

function updateHeader() {
  crumb.textContent = project ? `${project.title} / ${project.version}` : "";
  newButton.textContent = `＋ ${t("newProject")}`;
  exportButton.textContent = `↓ ${t("export")}`;
  newButton.classList.toggle("is-hidden", !project);
  exportButton.classList.toggle("is-hidden", !project);
  document.querySelectorAll("[data-i18n]").forEach(node => node.textContent = t(node.dataset.i18n));
}

function renderStart() {
  project = null;
  crumb.textContent = "";
  newButton.classList.add("is-hidden");
  exportButton.classList.add("is-hidden");
  const saved = readStoredProject();
  app.innerHTML = `<section class="start-screen utility-start">
    <div class="start-intro utility-intro"><div><span class="micro-label">ZAVOD / ${t("systemName")}</span><h1>${t("ingestTitle")}</h1><p>${t("ingestDesc")}</p></div>
      <div class="production-chain"><span class="chain-label">${t("outputMap")}</span><ol><li><b>01</b><span>${t("sourceStage")}</span><small>PDF · TXT · FOUNTAIN</small></li><li><b>02</b><span>${t("reviewStage")}</span><small>${t("navBreakdown")}</small></li><li><b>03</b><span>${t("planStage")}</span><small>${t("navSchedule")} · ${t("navShots")}</small></li><li><b>04</b><span>${t("executeStage")}</span><small>${t("navDayPack")}</small></li></ol></div>
      <div class="recent-project ${saved ? "" : "is-empty"}"><span>${t("lastProject")}</span>${saved ? `<button type="button" data-resume-project><b>${esc(saved.title)}</b><small>${saved.id} · ${saved.version} · ${saved.scenes?.length || 0} ${t("scenesCount")}</small><i>→</i></button>` : `<p>${t("noRecent")}</p>`}</div></div>
    <div class="source-panel"><span class="micro-label">${t("sourceKicker")}</span><h2>${t("sourceTitle")}</h2>
      <div class="source-types">${["logline","synopsis","screenplay"].map(type => `<button type="button" data-source-type="${type}" class="${sourceType === type ? "is-active" : ""}">${t(type)}</button>`).join("")}</div>
      <label class="drop-zone" data-drop-zone><input type="file" data-source-file accept=".pdf,.txt,.fountain,text/plain,application/pdf"><i>＋</i><strong>${t("uploadTitle")}</strong><small>${t("uploadHint")}</small></label>
      <div data-file-status></div><div class="source-separator">${t("or")}</div>
      <textarea class="source-text" data-source-text placeholder="${t("pastePlaceholder")}"></textarea>
      <div class="source-actions"><button type="button" data-use-sample>${t("useSample")}</button><button type="button" class="primary" data-analyze>${t("analyze")}</button></div>
      <div class="source-error" data-source-error aria-live="polite"></div><p class="privacy-note">${t("privacy")}</p>
    </div></section>`;
  bindStartEvents();
}

function bindStartEvents() {
  const textArea = app.querySelector("[data-source-text]");
  const fileInput = app.querySelector("[data-source-file]");
  const dropZone = app.querySelector("[data-drop-zone]");
  app.querySelectorAll("[data-source-type]").forEach(button => button.addEventListener("click", () => { sourceType = button.dataset.sourceType; app.querySelectorAll("[data-source-type]").forEach(item => item.classList.toggle("is-active", item === button)); }));
  fileInput.addEventListener("change", () => handleFile(fileInput.files[0]));
  dropZone.addEventListener("dragover", event => { event.preventDefault(); dropZone.classList.add("is-dragging"); });
  dropZone.addEventListener("dragleave", () => dropZone.classList.remove("is-dragging"));
  dropZone.addEventListener("drop", event => { event.preventDefault(); dropZone.classList.remove("is-dragging"); handleFile(event.dataTransfer.files[0]); });
  app.querySelector("[data-use-sample]").addEventListener("click", () => { const sampleNames = { hy: "Լռության գինը.fountain", ru: "Цена тишины.fountain", en: "The Price of Silence.fountain" }; sourceType = "screenplay"; sourceFile = { name: sampleNames[language], size: samples[language].length, kind: "text" }; sourcePdfPages = null; textArea.value = samples[language]; renderFileStatus(); app.querySelectorAll("[data-source-type]").forEach(item => item.classList.toggle("is-active", item.dataset.sourceType === "screenplay")); });
  app.querySelector("[data-analyze]").addEventListener("click", () => analyzeInput(textArea.value));
  app.querySelector("[data-resume-project]")?.addEventListener("click", () => {
    project = hydrateProject(readStoredProject());
    if (!project) return;
    activeView = "overview";
    activeSceneId = project.scenes[0]?.id || null;
    activeDay = project.schedule[0]?.number || 1;
    renderWorkspace();
    updateHeader();
  });
}

function readStoredProject() {
  try { return JSON.parse(localStorage.getItem("zavod-current-project") || "null"); }
  catch { return null; }
}

function hydrateProject(value) {
  if (!value || typeof value !== "object") return null;
  value.schemaVersion = 2;
  value.scenes = Array.isArray(value.scenes) ? value.scenes.map((scene, index) => ({
    ...scene,
    id: scene.id || `SC-${String(index + 1).padStart(3, "0")}`,
    status: scene.status || "draft",
    confidence: scene.confidence || Math.max(55, 96 - (scene.time === "—" ? 18 : 0) - (!scene.cast?.length ? 10 : 0)),
    notes: scene.notes || ""
  })) : [];
  value.schedule = Array.isArray(value.schedule) ? value.schedule : createSchedule(value.scenes);
  value.shotsByScene = value.shotsByScene || Object.fromEntries(value.scenes.map(scene => [scene.id, createShotDrafts(scene)]));
  value.artifacts = value.artifacts || { breakdown: "review", schedule: "draft", shots: "draft", deck: "draft", daypack: "draft" };
  value.stale = value.stale || { schedule: false, shots: false, deck: false, daypack: false };
  value.dayMeta = value.dayMeta || {};
  value.approvalHistory = value.approvalHistory || [];
  return value;
}

async function handleFile(file) {
  const errorNode = app.querySelector("[data-source-error]");
  if (!file) return;
  if (file.size > 30 * 1024 * 1024) { errorNode.textContent = t("errSize"); return; }
  const extension = file.name.split(".").pop().toLowerCase();
  if (!["pdf", "txt", "fountain"].includes(extension)) { errorNode.textContent = t("errType"); return; }
  errorNode.textContent = "";
  sourceFile = { name: file.name, size: file.size, kind: extension };
  sourcePdfPages = null;
  renderFileStatus(true);
  try {
    if (extension === "pdf") {
      const data = await fileToBase64(file);
      const response = await fetch("/api/extract-pdf", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: file.name, data }) });
      if (!response.ok) throw new Error("PDF");
      const result = await response.json();
      if (!result.text?.trim()) throw new Error("PDF");
      sourcePdfPages = result.pages;
      app.querySelector("[data-source-text]").value = result.text;
    } else {
      app.querySelector("[data-source-text]").value = (await file.text()).replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n");
    }
    renderFileStatus(false);
  } catch {
    sourceFile = null;
    renderFileStatus();
    errorNode.textContent = t("errPdf");
  }
}

function fileToBase64(file) {
  return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1]); reader.onerror = reject; reader.readAsDataURL(file); });
}

function renderFileStatus(loading = false) {
  const node = app.querySelector("[data-file-status]");
  if (!node) return;
  node.innerHTML = sourceFile ? `<div class="file-pill"><span><b>${esc(sourceFile.name)}</b> · ${formatBytes(sourceFile.size)}${loading ? " · …" : ""}</span><button type="button" data-remove-file aria-label="Remove">×</button></div>` : "";
  node.querySelector("[data-remove-file]")?.addEventListener("click", () => { sourceFile = null; sourcePdfPages = null; app.querySelector("[data-source-file]").value = ""; node.innerHTML = ""; });
}

function formatBytes(bytes) { return bytes > 1048576 ? `${(bytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`; }

async function analyzeInput(rawText) {
  const text = rawText.trim();
  if (!text) { app.querySelector("[data-source-error]").textContent = t("errEmpty"); return; }
  app.innerHTML = `<section class="processing"><div class="processing-inner"><span class="processing-code">${t("processingCode")}</span><h2>${t("processing")}</h2><div class="process-line"><i></i></div><p>${t("processingNote")}</p></div></section>`;
  await new Promise(resolve => setTimeout(resolve, 650));
  project = buildProject(text);
  activeView = "overview";
  activeSceneId = project.scenes[0]?.id || null;
  activeSlide = 0;
  saveProject();
  renderWorkspace();
  updateHeader();
}

function buildProject(source) {
  const scenes = sourceType === "screenplay" ? parseScenes(source) : [];
  const title = deriveTitle(source);
  const characters = unique(scenes.flatMap(scene => scene.cast));
  const locations = unique(scenes.map(scene => scene.location));
  const schedule = createSchedule(scenes);
  const pageEstimate = Math.max(1, Math.round(source.length / 1800));
  const warnings = [];
  if (sourceType === "screenplay" && !scenes.length) warnings.push("NO_SCENES");
  if (sourceType !== "screenplay") warnings.push("LIMITED_SOURCE");
  if (scenes.some(scene => scene.time === "—")) warnings.push("MISSING_TIME");
  const completeness = sourceType !== "screenplay" ? 28 : Math.min(92, 45 + (scenes.length ? 15 : 0) + (characters.length ? 12 : 0) + (locations.length ? 10 : 0) + (!warnings.includes("MISSING_TIME") ? 10 : 0));
  const shotsByScene = Object.fromEntries(scenes.map(scene => [scene.id, createShotDrafts(scene)]));
  return {
    schemaVersion: 2, parserVersion: "0.2.0", id: `ZV-${Date.now().toString().slice(-6)}`, title, version: "v1", sourceType, source,
    sourceFile: sourceFile?.name || null, sourcePdfPages, createdAt: new Date().toISOString(), pageEstimate, scenes, characters, locations, schedule, warnings, completeness,
    synopsis: sourceType === "logline" ? source : source.split(/\n\s*\n/).filter(Boolean).slice(0, 2).join(" ").slice(0, 650),
    shotsByScene,
    artifacts: { breakdown: scenes.length ? "review" : "draft", schedule: "draft", shots: "draft", deck: "draft", daypack: "draft" },
    stale: { schedule: false, shots: false, deck: false, daypack: false },
    dayMeta: {}, approvalHistory: []
  };
}

function deriveTitle(source) {
  if (sourceFile) return sourceFile.name.replace(/\.(pdf|txt|fountain)$/i, "").trim() || t("unnamed");
  const candidate = source.split("\n").map(line => line.trim()).find(line => line && line.length < 90 && !isSceneHeading(line));
  return candidate || t("unnamed");
}

function isSceneHeading(line) {
  return /^(INT\.?|EXT\.?|INT\.?\s*\/\s*EXT\.?|I\/E\.?|ИНТ\.?|НАТ\.?|ИНТ\.?\s*\/\s*НАТ\.?|ՆԵՐՔ\.?|ԴՈՒՐՍ\.?|ԻՆՏ\.?|ԷՔՍՏ\.?)\s+/iu.test(line.trim());
}

function parseScenes(source) {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  const sceneStarts = [];
  lines.forEach((line, index) => { if (isSceneHeading(line)) sceneStarts.push({ index, heading: line.trim() }); });
  return sceneStarts.map((start, sceneIndex) => {
    const end = sceneStarts[sceneIndex + 1]?.index ?? lines.length;
    const bodyLines = lines.slice(start.index + 1, end);
    const body = bodyLines.join("\n").trim();
    const heading = start.heading;
    const exterior = /^(EXT|НАТ|ԴՈՒՐՍ|ԷՔՍՏ)/iu.test(heading);
    const timeMatch = heading.match(/(?:—|-|–)\s*(DAY|NIGHT|MORNING|EVENING|DAWN|DUSK|ДЕНЬ|НОЧЬ|УТРО|ВЕЧЕР|РАССВЕТ|ЗАКАТ|ՕՐ|ԳԻՇԵՐ|ԱՌԱՎՈՏ|ԵՐԵԿՈ|ԼՈՒՍԱԲԱՑ|ՄԱՅՐԱՄՈՒՏ)\s*$/iu);
    const time = timeMatch ? timeMatch[1] : "—";
    const location = heading.replace(/^(INT\.?|EXT\.?|INT\.?\s*\/\s*EXT\.?|I\/E\.?|ИНТ\.?|НАТ\.?|ИНТ\.?\s*\/\s*НАТ\.?|ՆԵՐՔ\.?|ԴՈՒՐՍ\.?|ԻՆՏ\.?|ԷՔՍՏ\.?)\s*/iu, "").replace(/(?:—|-|–)\s*(DAY|NIGHT|MORNING|EVENING|DAWN|DUSK|ДЕНЬ|НОЧЬ|УТРО|ВЕЧЕР|РАССВЕТ|ЗАКАТ|ՕՐ|ԳԻՇԵՐ|ԱՌԱՎՈՏ|ԵՐԵԿՈ|ԼՈՒՍԱԲԱՑ|ՄԱՅՐԱՄՈՒՏ)\s*$/iu, "").trim();
    const cast = detectCharacters(bodyLines);
    const elements = detectElements(body);
    const riskText = `${heading} ${body}`.toUpperCase();
    const riskMatches = [/(CAR|VEHICLE|МАШИН|АВТО|ՄԵՔԵՆԱ)/u, /(FIRE|ОГОНЬ|ПОЖАР|ԿՐԱԿ)/u, /(CROWD|ТОЛП|МАССОВ|ԱՄԲՈԽ|ԶԱՆԳՎԱԾ)/u, /(FIGHT|ПАДАЕТ|УДАР|ԿՌԻՎ|ԸՆԿՆՈՒՄ)/u, /(RAIN|ДОЖД|ԱՆՁՐԵՎ)/u].filter(regex => regex.test(riskText)).length;
    const complexity = Math.min(3, 1 + riskMatches + (exterior ? 1 : 0));
    const eighths = Math.min(8, Math.max(1, Math.ceil(body.length / 230)));
    const shootMinutes = 45 + cast.length * 12 + complexity * 22 + elements.length * 8;
    const confidence = Math.max(55, 96 - (time === "—" ? 18 : 0) - (!cast.length ? 10 : 0) - (!location ? 12 : 0));
    return { id: `SC-${String(sceneIndex + 1).padStart(3, "0")}`, number: sceneIndex + 1, heading, interior: !exterior, exterior, location: location || "—", time, body, cast, elements, complexity, eighths, shootMinutes, confidence, status: "draft", notes: "" };
  });
}

function detectCharacters(lines) {
  const blocked = /^(CUT TO|FADE|DISSOLVE|КОНЕЦ|СЦЕНА|ՕՐ|ԳԻՇԵՐ|ՆԵՐՔ|ԴՈՒՐՍ)/u;
  const result = [];
  lines.forEach((raw, index) => {
    const line = raw.trim().replace(/\s*\(.*\)\s*$/, "");
    if (!line || line.length > 42 || blocked.test(line.toUpperCase()) || /[.!?:,]$/.test(line)) return;
    const letters = line.replace(/[^\p{L}]/gu, "");
    const next = lines.slice(index + 1).find(value => value.trim())?.trim() || "";
    if (letters.length >= 2 && line === line.toUpperCase() && next && !isSceneHeading(line)) result.push(line);
  });
  return unique(result).slice(0, 20);
}

function detectElements(body) {
  const dictionaries = [
    ["phone", "телефон", "հեռախոս"], ["car", "машин", "автомоб", "մեքենա"], ["letter", "письм", "նամակ"], ["envelope", "конверт", "ծրար"],
    ["photo", "фото", "նկար"], ["gun", "пистолет", "оруж", "ատրճանակ", "զենք"], ["food", "еда", "блюд", "սնունդ"], ["glass", "стакан", "бокал", "բաժակ"],
    ["rain", "дожд", "անձրև"], ["music", "музык", "երաժշտ"], ["crowd", "толп", "массов", "ամբոխ", "զանգված"]
  ];
  const normalized = body.toLowerCase();
  return dictionaries.filter(words => words.some(word => normalized.includes(word))).map(words => words.find(word => normalized.includes(word))).slice(0, 12);
}

function createSchedule(scenes) {
  if (!scenes.length) return [];
  const sorted = [...scenes].sort((a, b) => a.location.localeCompare(b.location) || Number(a.exterior) - Number(b.exterior) || a.number - b.number);
  const days = [];
  let current = { number: 1, scenes: [], minutes: 0, locations: [] };
  sorted.forEach(scene => {
    if (current.scenes.length && current.minutes + scene.shootMinutes > 480) { days.push(current); current = { number: current.number + 1, scenes: [], minutes: 0, locations: [] }; }
    current.scenes.push(scene.id); current.minutes += scene.shootMinutes; current.locations = unique([...current.locations, scene.location]);
  });
  if (current.scenes.length) days.push(current);
  return days;
}

function createShotDrafts(scene) {
  const first = scene.cast[0] || "—";
  const second = scene.cast[1];
  const drafts = [
    { titleKey: "shotMaster", framing: "WS", lens: "24–28mm", movement: "STATIC", seconds: 8, description: `${scene.location}. ${scene.body.split(/(?<=[.!?])\s/)[0]?.slice(0, 180) || scene.heading}` },
    { titleKey: "shotMedium", framing: second ? "2S / MS" : "MS", lens: "35–50mm", movement: "STATIC", seconds: 12, description: second ? `${first} / ${second}` : first },
    { titleKey: "shotClose", framing: "CU", lens: "75–85mm", movement: "STATIC", seconds: 6, description: first }
  ];
  if (scene.elements.length) drafts.push({ titleKey: "shotInsert", framing: "INSERT", lens: "50–85mm", movement: "STATIC", seconds: 4, description: scene.elements.join(", ") });
  if (scene.exterior) drafts.push({ titleKey: "shotTransition", framing: "EWS", lens: "18–24mm", movement: "STATIC", seconds: 6, description: scene.location });
  return drafts.map((shot, index) => ({ ...shot, id: `${scene.id}-SH-${String(index + 1).padStart(2, "0")}`, status: "draft" }));
}

function markDownstreamStale() {
  project.stale = { schedule: true, shots: true, deck: true, daypack: true };
  ["schedule", "shots", "deck", "daypack"].forEach(key => { project.artifacts[key] = "stale"; });
}

function artifactStatus(key) {
  if (project.stale?.[key]) return "stale";
  return project.artifacts?.[key] || "draft";
}

function statusLabel(status) {
  return t(status === "approved" ? "statusApproved" : status === "review" ? "statusReview" : status === "stale" ? "statusStale" : "statusDraft");
}

function saveProject() {
  if (!project) return;
  try {
    localStorage.setItem("zavod-current-project", JSON.stringify(project));
    document.body.dataset.saveState = "saved";
  } catch {
    document.body.dataset.saveState = "failed";
    showToast(t("saveFailed"));
  }
}

function renderWorkspace() {
  updateHeader();
  const views = [
    ["source", "1", "navSource"], ["overview", "2", "navOverview"], ["breakdown", "3", "navBreakdown"],
    ["schedule", "4", "navSchedule"], ["shots", "5", "navShots"], ["deck", "6", "navDeck"], ["daypack", "7", "navDayPack"]
  ];
  app.innerHTML = `<section class="workspace-shell"><aside class="tool-rail"><div class="rail-project"><span>${project.id} / ${project.version}</span><h2>${esc(project.title)}</h2><p>${t(project.sourceType)} · ${project.sourceFile ? esc(project.sourceFile) : t("originalText")}</p></div>
    <nav class="tool-nav">${views.map(([view, no, label]) => `<button type="button" data-view="${view}" class="${activeView === view ? "is-active" : ""}"><i>${no}</i><span>${t(label)}</span><small>${view === "breakdown" ? project.scenes.length : view === "schedule" ? project.schedule.length : view === "daypack" ? statusLabel(artifactStatus("daypack")) : ""}</small></button>`).join("")}</nav>
    <div class="rail-completeness"><span>${t("completeness")}</span><b>${project.completeness}%</b><div class="mini-progress"><i style="--value:${project.completeness}%"></i></div></div></aside>
    <div class="workspace-main">${renderActiveView()}</div></section>`;
  app.querySelectorAll("[data-view]").forEach(button => button.addEventListener("click", () => { activeView = button.dataset.view; renderWorkspace(); }));
  bindWorkspaceEvents();
}

function viewHead(kicker, title, outline, actions = "") {
  return `<header class="workspace-head"><div><span class="micro-label">${kicker}</span><h1>${t(title)}<br><span>${t(outline)}</span></h1></div><div class="workspace-head-actions">${actions}<button type="button" class="outline-button" data-open-help>?</button></div></header>`;
}

function renderActiveView() {
  const renderers = { source: renderSourceView, overview: renderOverview, breakdown: renderBreakdown, schedule: renderSchedule, shots: renderShots, deck: renderDeck, daypack: renderDayPack };
  return (renderers[activeView] || renderOverview)();
}

function renderSourceView() {
  const warningLabels = project.warnings.map(code => code === "NO_SCENES" ? t("noSceneWarning") : code === "LIMITED_SOURCE" ? t("lowDataWarning") : code === "MISSING_TIME" ? `${t("time")}: ${t("missing")}` : code);
  return `${viewHead(`${project.id} / 01`, "sourceViewTitle", "sourceViewOutline")}
    <div class="notice"><span>${t("sourceLanguageNote")}</span></div>
    <div class="stat-grid"><article class="stat"><span>${t("sourceFile")}</span><b>${project.sourceFile ? esc(project.sourceFile.slice(0, 18)) : "—"}</b><small>${project.sourceFile ? "LOCAL" : "PASTED"}</small></article><article class="stat"><span>${t("sourceType")}</span><b>${t(project.sourceType)}</b></article><article class="stat"><span>${t("sourceLength")}</span><b>${project.source.length.toLocaleString()}</b></article><article class="stat"><span>${t("sourcePages")}</span><b>${project.sourcePdfPages || "—"}</b></article><article class="stat"><span>${t("warnings")}</span><b>${warningLabels.length}</b></article></div>
    <div class="content-grid"><section class="panel"><header class="panel-head"><h2>${t("originalText")}</h2><span>${project.version}</span></header><div class="panel-body"><pre style="white-space:pre-wrap;margin:0;font:12px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;max-height:600px;overflow:auto">${esc(project.source)}</pre></div></section>
    <section class="panel"><header class="panel-head"><h2>${t("warnings")}</h2><span>${warningLabels.length}</span></header><div class="panel-body"><div class="readiness-list">${warningLabels.length ? warningLabels.map(label => `<div class="readiness-row is-missing"><i>!</i><div><b>${esc(label)}</b></div></div>`).join("") : `<div class="readiness-row"><i>✓</i><div><b>${t("ready")}</b></div></div>`}</div></div></section></div>`;
}

function renderOverview() {
  const hasScenes = project.scenes.length > 0;
  const prepWeeks = Math.max(2, Math.ceil(project.pageEstimate / 25));
  const postWeeks = Math.max(2, Math.ceil(project.pageEstimate / 18));
  const checks = [
    [project.source.length > 100, t("path1"), project.sourceFile || t("originalText")], [hasScenes, t("scenes"), hasScenes ? `${project.scenes.length}` : t("missing")],
    [project.characters.length > 0, t("characters"), project.characters.length ? project.characters.slice(0, 3).join(", ") : t("missing")], [project.locations.length > 0, t("locations"), project.locations.length ? `${project.locations.length}` : t("missing")]
  ];
  const dependencies = ["breakdown", "schedule", "shots", "deck", "daypack"];
  const approvedCount = project.scenes.filter(scene => scene.status === "approved").length;
  return `${viewHead(`${project.id} / 02`, "overviewTitle", "overviewOutline")}
    <div class="notice"><span>${t("draftWarning")}</span>${!hasScenes ? `<button type="button" data-go-source>${t("addScript")}</button>` : ""}</div>
    <div class="stat-grid"><article class="stat"><span>${t("scenes")}</span><b>${project.scenes.length}</b></article><article class="stat"><span>${t("approvedScenes")}</span><b>${approvedCount}/${project.scenes.length}</b></article><article class="stat"><span>${t("locations")}</span><b>${project.locations.length}</b></article><article class="stat"><span>${t("pages")}</span><b>≈ ${project.pageEstimate}</b></article><article class="stat"><span>${t("shootDays")}</span><b>${project.schedule.length || "—"}</b></article></div>
    <div class="content-grid"><section class="panel"><header class="panel-head"><h2>${t("readiness")}</h2><span>${project.completeness}%</span></header><div class="panel-body"><div class="readiness-list">${checks.map(([ok, label, detail]) => `<div class="readiness-row ${ok ? "" : "is-missing"}"><i>${ok ? "✓" : "!"}</i><div><b>${label}</b><p>${esc(detail)}</p></div><small>${ok ? t("ready") : t("missing")}</small></div>`).join("")}</div></div></section>
    <section class="panel"><header class="panel-head"><h2>${t("roughTimeline")}</h2><span>DRAFT</span></header><div class="rough-timeline"><div class="timeline-part"><span>${t("preproduction")}</span><b>${prepWeeks}</b><small>WEEKS</small></div><div class="timeline-part"><span>${t("production")}</span><b>${project.schedule.length || "—"}</b><small>DAYS</small></div><div class="timeline-part"><span>${t("post")}</span><b>${postWeeks}</b><small>WEEKS</small></div></div></section></div>
    <section class="panel impact-panel"><header class="panel-head"><h2>${t("impactTitle")}</h2><span>${project.version}</span></header><div class="impact-flow">${dependencies.map((key, index) => `<button type="button" data-view="${key}" class="artifact-node is-${artifactStatus(key)}"><i>${String(index + 1).padStart(2,"0")}</i><b>${t(key === "breakdown" ? "navBreakdown" : key === "schedule" ? "navSchedule" : key === "shots" ? "navShots" : key === "deck" ? "navDeck" : "navDayPack")}</b><small>${statusLabel(artifactStatus(key))}</small></button>`).join("")}</div><p class="dependency-hint">${t("dependencyHint")}</p></section>`;
}

function lockedView(kicker, title, outline) {
  return `${viewHead(kicker, title, outline)}<div class="locked"><div><b>${t("sourceNeeded")}</b><p>${t("noScenes")}</p><button type="button" data-go-source>${t("addScript")}</button></div></div>`;
}

function renderBreakdown() {
  if (!project.scenes.length) return lockedView(`${project.id} / 03`, "breakdownTitle", "breakdownOutline");
  const filtered = project.scenes.filter(scene => sceneFilter === "all" || sceneFilter === "interior" && scene.interior || sceneFilter === "exterior" && scene.exterior || sceneFilter === "day" && /DAY|ДЕНЬ|ՕՐ|MORNING|УТРО|ԱՌԱՎՈՏ/iu.test(scene.time) || sceneFilter === "night" && /NIGHT|НОЧЬ|ԳԻՇԵՐ|EVENING|ВЕЧЕР|ԵՐԵԿՈ/iu.test(scene.time));
  const selected = projectScene(activeSceneId) || filtered[0] || project.scenes[0];
  activeSceneId = selected.id;
  const csvButton = `<button type="button" class="outline-button" data-export-csv>↓ ${t("exportCsv")}</button>`;
  return `${viewHead(`${project.id} / 03`, "breakdownTitle", "breakdownOutline", csvButton)}<div class="notice"><span>${t("draftWarning")}</span></div>
    <div class="table-tools"><div class="filter-group">${["all","interior","exterior","day","night"].map(filter => `<button type="button" data-scene-filter="${filter}" class="${sceneFilter === filter ? "is-active" : ""}">${t(filter)}</button>`).join("")}</div><span class="micro-label">${filtered.length} / ${project.scenes.length}</span></div>
    <div class="breakdown-workbench"><div class="data-table-wrap"><table class="data-table compact-table"><thead><tr><th>№</th><th>${t("heading")}</th><th>${t("place")}</th><th>${t("time")}</th><th>${t("cast")}</th><th>${t("shotStatus")}</th></tr></thead><tbody>${filtered.map(scene => `<tr class="${scene.id === selected.id ? "is-selected" : ""}" data-select-scene="${scene.id}"><td class="scene-no">${scene.number}</td><td class="scene-heading"><button type="button" data-select-scene="${scene.id}">${esc(scene.heading)}</button><small>${scene.eighths}/8 · ${scene.elements.length} ${t("elements").toLowerCase()}</small></td><td contenteditable="true" data-edit-scene="${scene.id}" data-field="location">${esc(scene.location)}</td><td contenteditable="true" data-edit-scene="${scene.id}" data-field="time">${esc(scene.time)}</td><td contenteditable="true" data-edit-scene="${scene.id}" data-field="cast">${esc(scene.cast.join(", ") || "")}</td><td><span class="status-chip is-${scene.status}">${statusLabel(scene.status)}</span></td></tr>`).join("")}</tbody></table></div>
      <aside class="scene-inspector"><header><div><span>${selected.id}</span><h2>${t("scene")} ${selected.number}</h2></div><span class="confidence-badge">${t("confidence")} <b>${selected.confidence}%</b></span></header>
        <section><label>${t("sourceExcerpt")}</label><blockquote>${esc(selected.body.slice(0, 520) || selected.heading)}</blockquote></section>
        <section><label>${t("departmentTags")}</label><div class="tag-list inspector-tags">${selected.elements.map((item,index) => `<button type="button" class="tag" data-remove-element="${index}">${esc(item)} ×</button>`).join("") || `<small>${t("missing")}</small>`}</div><div class="inline-add"><input type="text" data-new-element placeholder="${t("addElement")}"><button type="button" data-add-element>＋</button></div></section>
        <section><label>${t("notes")}</label><textarea data-scene-notes placeholder="${t("noNotes")}">${esc(selected.notes)}</textarea></section>
        <footer><span class="status-chip is-${selected.status}">${statusLabel(selected.status)}</span><button type="button" class="approve-button" data-approve-scene="${selected.id}">${selected.status === "approved" ? t("reopen") : t("approve")}</button></footer>
      </aside></div>`;
}

function renderSchedule() {
  if (!project.scenes.length) return lockedView(`${project.id} / 04`, "scheduleTitle", "scheduleOutline");
  const breakdownReady = artifactStatus("breakdown") === "approved";
  const refresh = project.stale.schedule ? `<button type="button" class="outline-button accent" data-refresh-schedule ${breakdownReady ? "" : "disabled"}>↻ ${t("regenerate")}</button>` : `<button type="button" class="outline-button accent" data-approve-artifact="schedule" ${breakdownReady ? "" : "disabled"}>${artifactStatus("schedule") === "approved" ? t("reopen") : t("scheduleLock")}</button>`;
  const notice = !breakdownReady ? `<div class="notice is-stale"><span>${t("navBreakdown")}: ${t("statusApproved")} → ${t("navSchedule")}</span></div>` : project.stale.schedule ? `<div class="notice is-stale"><span>${t("staleNote")}</span></div>` : `<div class="notice"><span>${t("draftSchedule")} ${t("draftWarning")}</span></div>`;
  return `${viewHead(`${project.id} / 04`, "scheduleTitle", "scheduleOutline", refresh)}${notice}
    <div class="schedule-list">${project.schedule.map((day, dayIndex) => { const scenes = day.scenes.map(projectScene).filter(Boolean); const cast = unique(scenes.flatMap(scene => scene.cast)); return `<article class="shoot-day"><div class="day-code"><span>SHOOT / ${String(day.number).padStart(2,"0")}</span><b>${t("dayLabel")} ${day.number}</b><small>${t("call")}: ${project.dayMeta?.[day.number]?.call || "07:00"}</small><em class="status-chip is-${artifactStatus("schedule")}">${statusLabel(artifactStatus("schedule"))}</em></div><div class="day-scenes">${scenes.map(scene => `<div class="day-scene"><b>${scene.number}</b><span>${esc(scene.location)}<small>${esc(scene.cast.join(", ") || "—")}</small></span><div class="scene-move"><button type="button" data-move-scene="${scene.id}" data-direction="-1" aria-label="${t("movePrev")}" ${dayIndex === 0 ? "disabled" : ""}>←</button><button type="button" data-move-scene="${scene.id}" data-direction="1" aria-label="${t("moveNext")}" ${dayIndex === project.schedule.length - 1 ? "disabled" : ""}>→</button></div></div>`).join("")}</div><div class="day-meta"><b>${day.minutes} ${t("minutes")}</b><small>${scenes.length} ${t("scenesCount")} · ${cast.length} ${t("characters").toLowerCase()}</small></div></article>`; }).join("")}</div>`;
}

function projectScene(id) { return project.scenes.find(scene => scene.id === id); }

function renderShots() {
  if (!project.scenes.length) return lockedView(`${project.id} / 05`, "shotsTitle", "shotsOutline");
  const scene = projectScene(activeSceneId) || project.scenes[0];
  activeSceneId = scene.id;
  const shots = project.shotsByScene[scene.id] || (project.shotsByScene[scene.id] = createShotDrafts(scene));
  const breakdownReady = artifactStatus("breakdown") === "approved";
  const shotsApproved = artifactStatus("shots") === "approved";
  const refresh = project.stale.shots ? `<button type="button" class="outline-button accent" data-refresh-shots ${breakdownReady ? "" : "disabled"}>↻ ${t("regenerate")}</button>` : `<button type="button" class="outline-button accent" data-approve-artifact="shots" ${breakdownReady ? "" : "disabled"}>${artifactStatus("shots") === "approved" ? t("reopen") : t("approve")}</button>`;
  const notice = !breakdownReady ? `<div class="notice is-stale"><span>${t("navBreakdown")}: ${t("statusApproved")} → ${t("navShots")}</span></div>` : project.stale.shots ? `<div class="notice is-stale"><span>${t("staleNote")}</span></div>` : `<div class="notice"><span>${t("draftWarning")}</span></div>`;
  return `${viewHead(`${project.id} / 05`, "shotsTitle", "shotsOutline", refresh)}${notice}
    <div class="shots-layout"><aside class="scene-selector"><header>${t("selectScene")}</header><div class="scene-selector-list">${project.scenes.map(item => `<button type="button" data-shot-scene="${item.id}" class="${item.id === scene.id ? "is-active" : ""}"><b>${item.number}. ${esc(item.location)}</b><small>${esc(item.time)} · ${item.cast.length} ${t("characters").toLowerCase()}</small></button>`).join("")}</div></aside>
    <div><div class="shot-command"><span class="status-chip is-${artifactStatus("shots")}">${statusLabel(artifactStatus("shots"))}</span><button type="button" data-add-shot="${scene.id}" ${shotsApproved ? "disabled" : ""}>＋ ${t("addShot")}</button></div><div class="storyboard-grid">${shots.map((shot, index) => `<article class="story-card ${shotsApproved ? "is-locked" : ""}"><div class="story-frame"><span>${scene.number}.${index + 1}</span><b contenteditable="${shotsApproved ? "false" : "true"}" data-shot-edit="${shot.id}" data-field="framing">${esc(shot.framing)}</b></div><div class="story-text"><div class="shot-card-head"><h3>${t(shot.titleKey) || esc(shot.titleKey)}</h3><button type="button" data-delete-shot="${shot.id}" aria-label="${t("deleteShot")}" ${shotsApproved ? "disabled" : ""}>×</button></div><p contenteditable="${shotsApproved ? "false" : "true"}" data-shot-edit="${shot.id}" data-field="description">${esc(shot.description)}</p><div class="story-meta"><label>${t("lens")}<input value="${esc(shot.lens)}" data-shot-input="${shot.id}" data-field="lens" ${shotsApproved ? "disabled" : ""}></label><label>${t("movement")}<input value="${esc(shot.movement)}" data-shot-input="${shot.id}" data-field="movement" ${shotsApproved ? "disabled" : ""}></label><label>${t("duration")}<input type="number" min="1" max="999" value="${shot.seconds}" data-shot-input="${shot.id}" data-field="seconds" ${shotsApproved ? "disabled" : ""}></label></div></div></article>`).join("")}</div></div></div>`;
}

function buildShots(scene) {
  return project.shotsByScene[scene.id] || (project.shotsByScene[scene.id] = createShotDrafts(scene));
}

function renderDeck() {
  const slides = deckSlides();
  const slide = slides[activeSlide] || slides[0];
  const breakdownReady = !project.scenes.length || artifactStatus("breakdown") === "approved";
  const download = `<button type="button" class="outline-button" data-download-deck>↓ ${t("downloadDeck")}</button>${project.stale.deck ? `<button type="button" class="outline-button accent" data-refresh-deck ${breakdownReady ? "" : "disabled"}>↻ ${t("regenerate")}</button>` : `<button type="button" class="outline-button accent" data-approve-artifact="deck" ${breakdownReady ? "" : "disabled"}>${artifactStatus("deck") === "approved" ? t("reopen") : t("approve")}</button>`}`;
  const notice = !breakdownReady ? `<div class="notice is-stale"><span>${t("navBreakdown")}: ${t("statusApproved")} → ${t("navDeck")}</span></div>` : project.stale.deck ? `<div class="notice is-stale"><span>${t("staleNote")}</span></div>` : "";
  return `${viewHead(`${project.id} / 06`, "deckTitle", "deckOutline", download)}${notice}<div class="deck-shell"><nav class="slide-list">${slides.map((item,index) => `<button type="button" data-slide="${index}" class="${index === activeSlide ? "is-active" : ""}"><b>${String(index+1).padStart(2,"0")}</b><span>${esc(item.label)}</span></button>`).join("")}</nav><div class="slide-preview-wrap"><article class="slide-preview"><span class="slide-no">${String(activeSlide+1).padStart(2,"0")} / ${String(slides.length).padStart(2,"0")} · ${project.id}</span><h2>${esc(slide.title)}</h2><p>${esc(slide.text)}</p>${slide.facts ? `<div class="slide-facts">${slide.facts.map(([label,value]) => `<span>${esc(label)}<b>${esc(value)}</b></span>`).join("")}</div>` : ""}<em>${t("operationalDraft")}</em></article></div></div>`;
}

function deckSlides() {
  const summary = project.synopsis || project.source.slice(0, 500);
  return [
    { label: t("slideTitle"), title: project.title, text: t("deckTagline"), facts: [["ID",project.id],[t("sourceType"),t(project.sourceType)],[t("pages"),`≈ ${project.pageEstimate}`],["VERSION",project.version]] },
    { label: t("slideStory"), title: t("slideStory"), text: summary.slice(0, 650) || t("deckStoryText") },
    { label: t("slideCharacters"), title: t("slideCharacters"), text: project.characters.join(" · ") || t("deckCharactersText"), facts: project.characters.slice(0,4).map(name => [name, `${project.scenes.filter(scene=>scene.cast.includes(name)).length} ${t("scenesCount")}`]) },
    { label: t("slideWorld"), title: t("slideWorld"), text: project.locations.join(" · ") || t("deckWorldText") },
    { label: t("slideProduction"), title: t("slideProduction"), text: t("deckProductionText"), facts: [[t("scenes"),String(project.scenes.length)],[t("shootDays"),String(project.schedule.length||"—")],[t("locations"),String(project.locations.length)],[t("characters"),String(project.characters.length)]] },
    { label: t("slideApproach"), title: t("slideApproach"), text: t("deckApproachText"), facts: [["WS","24–28mm"],["MS","35–50mm"],["CU","75–85mm"],["STATUS","DRAFT"]] }
  ];
}

function renderDayPack() {
  if (!project.schedule.length) return lockedView(`${project.id} / 07`, "dayPackTitle", "dayPackOutline");
  const day = project.schedule.find(item => item.number === activeDay) || project.schedule[0];
  activeDay = day.number;
  const scenes = day.scenes.map(projectScene).filter(Boolean);
  const cast = unique(scenes.flatMap(scene => scene.cast));
  const locations = unique(scenes.map(scene => scene.location));
  const elements = unique(scenes.flatMap(scene => scene.elements));
  const risks = unique(scenes.filter(scene => scene.complexity > 1).map(scene => `${t("scene")} ${scene.number} · ${scene.heading}`));
  const blocked = artifactStatus("schedule") !== "approved";
  const action = `<button type="button" class="outline-button" data-export-daypack ${blocked ? "disabled" : ""}>↓ ${t("exportDayPack")}</button>${blocked || project.stale.daypack ? `<button type="button" class="outline-button accent" data-refresh-daypack ${blocked ? "disabled" : ""}>↻ ${t("regenerate")}</button>` : `<button type="button" class="outline-button accent" data-approve-artifact="daypack">${artifactStatus("daypack") === "approved" ? t("reopen") : t("approve")}</button>`}`;
  return `${viewHead(`${project.id} / 07`, "dayPackTitle", "dayPackOutline", action)}${blocked ? `<div class="notice is-stale"><span>${t("scheduleLock")}: ${t("statusApproved")} → ${t("callSheet")}</span></div>` : project.stale.daypack ? `<div class="notice is-stale"><span>${t("staleNote")}</span></div>` : ""}
    <div class="day-tabs">${project.schedule.map(item => `<button type="button" data-day="${item.number}" class="${item.number === day.number ? "is-active" : ""}">${t("dayLabel")} ${item.number}</button>`).join("")}</div>
    <section class="call-sheet"><header><div><span>${project.id} / ${String(day.number).padStart(2,"0")}</span><h2>${t("callSheet")}</h2></div><label>${t("callTime")}<input type="time" data-call-time value="${project.dayMeta?.[day.number]?.call || "07:00"}"></label><div class="call-status"><span class="status-chip is-${blocked ? "stale" : artifactStatus("daypack")}">${blocked ? t("statusStale") : statusLabel(artifactStatus("daypack"))}</span><small>${t("operationalDraft")}</small></div></header>
      <div class="call-summary"><article><span>${t("scenes")}</span><b>${scenes.length}</b></article><article><span>${t("characters")}</span><b>${cast.length}</b></article><article><span>${t("locations")}</span><b>${locations.length}</b></article><article><span>${t("estimated")}</span><b>${day.minutes} ${t("minutes")}</b></article></div>
      <div class="call-grid"><section><h3>${t("scheduleTitle")}</h3>${scenes.map(scene => `<div class="call-row"><b>${scene.number}</b><span>${esc(scene.heading)}<small>${esc(scene.cast.join(", ") || "—")}</small></span><em>${scene.shootMinutes} ${t("minutes")}</em></div>`).join("")}</section>
      <section><h3>${t("locationsLabel")}</h3>${locations.map(location => `<p>${esc(location)}</p>`).join("")}<h3>${t("departmentPack")}</h3><div class="tag-list">${elements.map(item => `<span class="tag">${esc(item)}</span>`).join("") || "—"}</div><h3>${t("dayRisks")}</h3>${risks.map(item => `<p class="risk-line">${esc(item)}</p>`).join("") || `<p>${t("notVerified")}</p>`}</section></div>
    </section>`;
}

function bindWorkspaceEvents() {
  app.querySelector("[data-open-help]")?.addEventListener("click", openHelp);
  app.querySelector("[data-go-source]")?.addEventListener("click", resetProject);
  app.querySelectorAll("[data-scene-filter]").forEach(button => button.addEventListener("click", () => { sceneFilter = button.dataset.sceneFilter; renderWorkspace(); }));
  app.querySelector("[data-export-csv]")?.addEventListener("click", exportBreakdownCsv);
  app.querySelectorAll("[data-edit-scene]").forEach(cell => cell.addEventListener("blur", () => {
    const scene = projectScene(cell.dataset.editScene); const raw = cell.textContent.trim();
    scene[cell.dataset.field] = cell.dataset.field === "cast" ? raw.split(",").map(item => item.trim()).filter(Boolean) : (raw || "—");
    scene.status = "review";
    touchBreakdown();
  }));
  app.querySelectorAll("button[data-select-scene]").forEach(button => button.addEventListener("click", () => { activeSceneId = button.dataset.selectScene; renderWorkspace(); }));
  app.querySelector("[data-approve-scene]")?.addEventListener("click", event => {
    const scene = projectScene(event.currentTarget.dataset.approveScene);
    scene.status = scene.status === "approved" ? "review" : "approved";
    project.artifacts.breakdown = project.scenes.every(item => item.status === "approved") ? "approved" : "review";
    recordApproval("scene", scene.id, scene.status);
    saveProject(); renderWorkspace();
  });
  app.querySelector("[data-scene-notes]")?.addEventListener("change", event => { projectScene(activeSceneId).notes = event.target.value.trim(); saveProject(); showToast(t("saved")); });
  app.querySelector("[data-add-element]")?.addEventListener("click", () => {
    const input = app.querySelector("[data-new-element]"); const value = input.value.trim(); if (!value) return;
    projectScene(activeSceneId).elements = unique([...projectScene(activeSceneId).elements, value]); projectScene(activeSceneId).status = "review"; touchBreakdown(); renderWorkspace();
  });
  app.querySelectorAll("[data-remove-element]").forEach(button => button.addEventListener("click", () => { projectScene(activeSceneId).elements.splice(Number(button.dataset.removeElement), 1); projectScene(activeSceneId).status = "review"; touchBreakdown(); renderWorkspace(); }));
  app.querySelector("[data-refresh-schedule]")?.addEventListener("click", () => { if (artifactStatus("breakdown") !== "approved") return; project.schedule = createSchedule(project.scenes); project.stale.schedule = false; project.artifacts.schedule = "review"; project.stale.daypack = true; project.artifacts.daypack = "stale"; activeDay = 1; saveProject(); renderWorkspace(); });
  app.querySelectorAll("[data-move-scene]").forEach(button => button.addEventListener("click", () => moveSceneBetweenDays(button.dataset.moveScene, Number(button.dataset.direction))));
  app.querySelector("[data-refresh-shots]")?.addEventListener("click", () => { if (artifactStatus("breakdown") !== "approved") return; project.shotsByScene = Object.fromEntries(project.scenes.map(scene => [scene.id, createShotDrafts(scene)])); project.stale.shots = false; project.artifacts.shots = "review"; saveProject(); renderWorkspace(); });
  app.querySelectorAll("[data-shot-scene]").forEach(button => button.addEventListener("click", () => { activeSceneId = button.dataset.shotScene; renderWorkspace(); }));
  app.querySelector("[data-add-shot]")?.addEventListener("click", event => { const sceneId = event.currentTarget.dataset.addShot; const list = project.shotsByScene[sceneId]; list.push({ id: `${sceneId}-SH-${Date.now().toString().slice(-5)}`, titleKey: "shotMedium", framing: "MS", lens: "50mm", movement: "STATIC", seconds: 6, description: "", status: "draft" }); project.artifacts.shots = "review"; saveProject(); renderWorkspace(); });
  app.querySelectorAll("[data-delete-shot]").forEach(button => button.addEventListener("click", () => { const list = project.shotsByScene[activeSceneId]; project.shotsByScene[activeSceneId] = list.filter(shot => shot.id !== button.dataset.deleteShot); project.artifacts.shots = "review"; saveProject(); renderWorkspace(); }));
  app.querySelectorAll("[data-shot-edit]").forEach(node => node.addEventListener("blur", () => { const shot = findShot(node.dataset.shotEdit); if (!shot) return; shot[node.dataset.field] = node.textContent.trim(); project.artifacts.shots = "review"; saveProject(); }));
  app.querySelectorAll("[data-shot-input]").forEach(input => {
    const updateShotField = () => { const shot = findShot(input.dataset.shotInput); if (!shot) return; shot[input.dataset.field] = input.dataset.field === "seconds" ? Number(input.value) : input.value.trim(); project.artifacts.shots = "review"; saveProject(); };
    input.addEventListener("input", updateShotField);
    input.addEventListener("change", () => { updateShotField(); renderWorkspace(); });
  });
  app.querySelectorAll("[data-slide]").forEach(button => button.addEventListener("click", () => { activeSlide = Number(button.dataset.slide); renderWorkspace(); }));
  app.querySelector("[data-refresh-deck]")?.addEventListener("click", () => { if (project.scenes.length && artifactStatus("breakdown") !== "approved") return; project.stale.deck = false; project.artifacts.deck = "review"; saveProject(); renderWorkspace(); });
  app.querySelector("[data-download-deck]")?.addEventListener("click", downloadDeck);
  app.querySelectorAll("[data-approve-artifact]").forEach(button => button.addEventListener("click", () => toggleArtifact(button.dataset.approveArtifact)));
  app.querySelectorAll("[data-day]").forEach(button => button.addEventListener("click", () => { activeDay = Number(button.dataset.day); renderWorkspace(); }));
  app.querySelector("[data-call-time]")?.addEventListener("change", event => { project.dayMeta[activeDay] = { ...(project.dayMeta[activeDay] || {}), call: event.target.value }; project.artifacts.daypack = "review"; saveProject(); });
  app.querySelector("[data-refresh-daypack]")?.addEventListener("click", () => { if (artifactStatus("schedule") !== "approved") return; project.stale.daypack = false; project.artifacts.daypack = "review"; saveProject(); renderWorkspace(); });
  app.querySelector("[data-export-daypack]")?.addEventListener("click", downloadDayPack);
}

function touchBreakdown() {
  project.characters = unique(project.scenes.flatMap(item => item.cast).filter(item => item !== "—"));
  project.locations = unique(project.scenes.map(item => item.location).filter(item => item !== "—"));
  project.artifacts.breakdown = "review";
  project.version = `v${Number(project.version.slice(1) || 1) + 1}`;
  markDownstreamStale();
  saveProject(); showToast(t("saved")); updateHeader();
}

function recalculateDay(day) {
  const scenes = day.scenes.map(projectScene).filter(Boolean);
  day.minutes = scenes.reduce((sum, scene) => sum + scene.shootMinutes, 0);
  day.locations = unique(scenes.map(scene => scene.location));
}

function moveSceneBetweenDays(sceneId, direction) {
  const fromIndex = project.schedule.findIndex(day => day.scenes.includes(sceneId));
  const toIndex = fromIndex + direction;
  if (fromIndex < 0 || toIndex < 0 || toIndex >= project.schedule.length) return;
  project.schedule[fromIndex].scenes = project.schedule[fromIndex].scenes.filter(id => id !== sceneId);
  project.schedule[toIndex].scenes.push(sceneId);
  recalculateDay(project.schedule[fromIndex]); recalculateDay(project.schedule[toIndex]);
  project.artifacts.schedule = "review"; project.stale.daypack = true; project.artifacts.daypack = "stale";
  saveProject(); renderWorkspace();
}

function findShot(id) {
  return Object.values(project.shotsByScene || {}).flat().find(shot => shot.id === id);
}

function recordApproval(type, id, decision) {
  project.approvalHistory.push({ type, id, decision, version: project.version, at: new Date().toISOString() });
}

function toggleArtifact(key) {
  if (project.stale?.[key]) return;
  if (["schedule", "shots", "deck"].includes(key) && project.scenes.length && artifactStatus("breakdown") !== "approved") return;
  const next = artifactStatus(key) === "approved" ? "review" : "approved";
  project.artifacts[key] = next;
  if (key === "schedule" && next !== "approved") { project.stale.daypack = true; project.artifacts.daypack = "stale"; }
  if (key === "schedule" && next === "approved") { project.stale.daypack = false; project.artifacts.daypack = "draft"; }
  recordApproval("artifact", key, next); saveProject(); renderWorkspace();
}

function exportProject() {
  if (!project) return;
  download(`${slug(project.title)}-zavod.json`, JSON.stringify(project, null, 2), "application/json"); showToast(t("exported"));
}

function exportBreakdownCsv() {
  const headers = ["scene","heading","location","time","cast","elements","complexity","page_eighths"];
  const rows = project.scenes.map(scene => [scene.number,scene.heading,scene.location,scene.time,scene.cast.join(" | "),scene.elements.join(" | "),scene.complexity,scene.eighths].map(csvCell).join(","));
  download(`${slug(project.title)}-breakdown.csv`, `\uFEFF${headers.join(",")}\n${rows.join("\n")}`, "text/csv;charset=utf-8");
}
function csvCell(value) { return `"${String(value).replaceAll('"','""')}"`; }

function downloadDeck() {
  const slides = deckSlides();
  const html = `<!doctype html><html lang="${language}"><meta charset="utf-8"><title>${esc(project.title)}</title><style>body{margin:0;background:#ddd;font-family:Arial,sans-serif}.slide{box-sizing:border-box;width:100vw;min-height:56.25vw;padding:7vw;page-break-after:always;background:#111;color:#f4f3ef;display:flex;flex-direction:column;justify-content:space-between}.no{color:#f04b23;font-size:1vw}.slide h1{max-width:80%;margin:0;font-size:7vw;line-height:.9;text-transform:uppercase}.slide p{max-width:70%;font-size:1.4vw;line-height:1.5;color:#aaa}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:2vw}.facts span{border-top:1px solid #555;padding-top:1vw;color:#888;font-size:.8vw}.facts b{display:block;color:#fff;font-size:1.2vw;margin-top:.5vw}@media print{.slide{width:13.333in;min-height:7.5in}}</style><body>${slides.map((slide,index)=>`<section class="slide"><span class="no">${String(index+1).padStart(2,"0")} / ${String(slides.length).padStart(2,"0")} · ${esc(project.id)}</span><h1>${esc(slide.title)}</h1><p>${esc(slide.text)}</p>${slide.facts?`<div class="facts">${slide.facts.map(([label,value])=>`<span>${esc(label)}<b>${esc(value)}</b></span>`).join("")}</div>`:""}</section>`).join("")}</body></html>`;
  download(`${slug(project.title)}-pitch-deck.html`, html, "text/html;charset=utf-8"); showToast(t("deckExported"));
}

function downloadDayPack() {
  const day = project.schedule.find(item => item.number === activeDay) || project.schedule[0];
  const scenes = day.scenes.map(projectScene).filter(Boolean);
  const cast = unique(scenes.flatMap(scene => scene.cast));
  const locations = unique(scenes.map(scene => scene.location));
  const elements = unique(scenes.flatMap(scene => scene.elements));
  const html = `<!doctype html><html lang="${language}"><meta charset="utf-8"><title>${esc(project.title)} · ${t("dayLabel")} ${day.number}</title><style>body{margin:0;padding:40px;color:#111;background:#f4f3ef;font-family:Arial,sans-serif}header{display:flex;justify-content:space-between;border-bottom:4px solid #111;padding-bottom:20px}h1{margin:0;font-size:44px;text-transform:uppercase}.meta{font-size:12px;text-align:right}table{width:100%;border-collapse:collapse;margin:30px 0}th,td{padding:12px;border:1px solid #999;text-align:left;font-size:12px}th{background:#111;color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:30px}.box{border-top:3px solid #f04b23}.box h2{font-size:16px}.tag{display:inline-block;margin:3px;padding:6px;border:1px solid #999;font-size:10px}.warning{margin-top:40px;padding:14px;background:#fff0db;font-size:11px}@media print{body{padding:20px}}</style><body><header><div><small>${esc(project.id)} / ${esc(project.version)}</small><h1>${t("callSheet")}</h1><p>${esc(project.title)} · ${t("dayLabel")} ${day.number}</p></div><div class="meta"><b>${t("callTime")}</b><br>${project.dayMeta?.[day.number]?.call || "07:00"}<br><br>${statusLabel(artifactStatus("daypack"))}</div></header><table><thead><tr><th>№</th><th>${t("heading")}</th><th>${t("cast")}</th><th>${t("estimated")}</th></tr></thead><tbody>${scenes.map(scene => `<tr><td>${scene.number}</td><td>${esc(scene.heading)}</td><td>${esc(scene.cast.join(", "))}</td><td>${scene.shootMinutes} ${t("minutes")}</td></tr>`).join("")}</tbody></table><div class="grid"><section class="box"><h2>${t("characters")}</h2><p>${esc(cast.join(" · ") || "—")}</p><h2>${t("locationsLabel")}</h2><p>${esc(locations.join(" · ") || "—")}</p></section><section class="box"><h2>${t("departmentPack")}</h2>${elements.map(item => `<span class="tag">${esc(item)}</span>`).join("") || "—"}</section></div><p class="warning">${t("operationalDraft")}</p></body></html>`;
  download(`${slug(project.title)}-day-${day.number}-pack.html`, html, "text/html;charset=utf-8");
  showToast(t("exported"));
}

function download(name, content, type) { const blob = new Blob([content], { type }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = name; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }

function openHelp() {
  document.querySelector("[data-help-content]").innerHTML = `<h3>01 / ${t("path2")}</h3><p>${t("helpBody1")}</p><h3>02 / HUMAN CHECK</h3><p>${t("helpBody2")}</p>`;
  document.querySelector("[data-i18n='helpTitle']").textContent = t("helpTitle");
  helpDialog.showModal();
}
function showToast(message) { toast.textContent = message; toast.classList.add("is-visible"); clearTimeout(showToast.timer); showToast.timer = setTimeout(()=>toast.classList.remove("is-visible"),2300); }
function resetProject() { if (project && !confirm(t("confirmReset"))) return; project = null; sourceFile = null; sourcePdfPages = null; sourceType = "screenplay"; activeDay = 1; localStorage.removeItem("zavod-current-project"); renderStart(); updateHeader(); }

document.querySelectorAll("[data-lang]").forEach(button => button.addEventListener("click", () => setLanguage(button.dataset.lang)));
document.querySelector("[data-home]").addEventListener("click", () => project ? (activeView="overview",renderWorkspace()) : renderStart());
newButton.addEventListener("click", resetProject);
exportButton.addEventListener("click", exportProject);
document.querySelector("[data-close-help]").addEventListener("click", () => helpDialog.close());
helpDialog.addEventListener("click", event => { if (event.target === helpDialog) helpDialog.close(); });

setLanguage(language);
